SELECT /*selectExportExIvExportWarhsngProcDetail*/ A.STATUS, A.BUYER_NAME, A.PO_CREATE_DATE, A.RD_DATE, DECODE(A.ADD_USER_TEL,' ',A.ADD_USER_NAME,A.ADD_USER_NAME||'(' ||ADD_USER_TEL||')') ADD_USER_NAME, A.ADD_USER_NAME ADD_USER_NAME_ORG, A.ADD_USER_TEL, DECODE(A.AGENT_TEL_NO,' ' ,A.AGENT_NAME,A.AGENT_NAME||'('||AGENT_TEL_NO||')') AGENT_NAME, A.AGENT_NAME AGENT_NAME_ORG, A.AGENT_TEL_NO, A.PO_NO, A.LEGACY_PO_NO, A.LEGACY_PO_SEQ, A.INV_NO, A.ITEM_AMT, A.AGENT, A.BUYER, CASE WHEN (sysdate+7)-next_day(sysdate,1)+1 = 6 THEN sysdate+3 WHEN (sysdate+7)-next_day(sysdate,1)+1 = 7 THEN sysdate+2 ELSE SYSDATE+1 END SCHEDULED_DATE, A.DELY_TO_LOCATION, DECODE(A.DELY_TO_LOCATION,'','1','0') AS DELY_TO_LOCATION_IMG, A.PO_REMARK, DECODE(A.PO_REMARK,'','1','0') AS PO_REMARK_IMG, A.DELAY_REMARK, DECODE(A.DELAY_REMARK,'','1','0') AS DELAY_REMARK_IMG, A.INV_DATE, A.PROCESS_TYPE, A.PLANT, A.OVERSEA_TO_LOCATION, A.PURCHASE_DEPT, A.PO_SEQ, A.BUYER_ITEM_NO, A.DESCRIPTION_ENG, A.DESCRIPTION, A.SPECIFICATION, A.INV_QTY, A.UNIT_MEASURE, DECODE(A.BUYER, 'KRSAMS0123', A.PURCHASER_SAMS, (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.PURCHASER_ID)) AS PURCHASER, A.EXP_FOR_UNIT_PRICE, A.EXP_FOR_ITEM_AMT, A.ORIGIN_NAME, A.ACCOUNT_TYPE, A.MAKER_NAME||'('||(SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = A.MAKER_CODE)||')' AS MAKER, ' ' AS EMPTY, -- 엑셀 파일 내 공백 처리용 ' ' AS EMPTY2, -- 엑셀 파일 내 공백 처리용 A.RECIPIENT_NAME AS RECIPIENT_NAME FROM ( SELECT '발주' AS STATUS, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER) AS BUYER_NAME, POHD.PO_CREATE_DATE AS PO_CREATE_DATE, PODT.RD_DATE AS RD_DATE, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_TEL_NO, PODT.PO_NO AS PO_NO, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, '' AS INV_NO, PODT.ITEM_AMT AS ITEM_AMT, POHD.AGENT AS AGENT, PODT.BUYER AS BUYER, POHD.PO_REMARK AS PO_REMARK, PODT.DELAY_REMARK, PODT.SCM_REMARK AS SCM_REMARK, '' INV_DATE, PODT.PROCESS_TYPE AS PROCESS_TYPE, PODT.PLANT AS PLANT, POHD.OVERSEA_TO_LOCATION AS OVERSEA_TO_LOCATION, COD2.TEXT1 AS PURCHASE_DEPT, PODT.PO_SEQ, PODT.BUYER_ITEM_NO, BYIT.DESCRIPTION_ENG, PODT.DESCRIPTION, PODT.SPECIFICATION, PODT.ITEM_QTY AS INV_QTY, PODT.UNIT_MEASURE, PRDT.PURCHASER_ID, PRDT.EXP_FOR_UNIT_PRICE, PRDT.EXP_FOR_ITEM_AMT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = PODT.ORIGIN_CODE) AS ORIGIN_NAME, PODT.ACCOUNT_TYPE, PODT.MAKER_NAME, PODT.MAKER_CODE, NVL(F_SPLIT(PRDT.IV_COLUMN,'^',7), ' ') AS PURCHASER_SAMS, PRDT.RECIPIENT_NAME FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, ICOMCOD2 COD2, ICOMBYIT BYIT WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.ITEM_QTY > PODT.IV_QTY AND PODT.BYIT_COMORG_CODE = BYIT.BUYER AND PODT.BUYER_ITEM_NO = BYIT.BUYER_ITEM_NO AND PODT.COMPLETE_MARK = 'N' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND PRDT.BUYER = COD2.COMPANY_CODE(+) AND COD2.TYPE(+) = 'C001' AND PRDT.PURCHASER_DEPT = COD2.CODE(+) AND POHD.PKG_COMPANY_CODE =#{st_pkg_cmpy_no} AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND PRDT.EXP_CUR IS NOT NULL
AND PODT.BUYER IN
#{item}
AND PODT.PO_NO LIKE #{st_inv_no}||'%'
AND POHD.AGENT = #{st_agent_code}
AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_purchase_dept}||'%')
AND PODT.PO_NO IN
#{item}
AND PODT.PO_NO LIKE #{st_po_no}||'%'
AND PODT.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
UNION ALL SELECT DECODE(PODT.ITEM_QTY,IVDT.INV_QTY,'입고예정','분할입고예정') AS STATUS, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER) AS BUYER_NAME, POHD.PO_CREATE_DATE AS PO_CREATE_DATE, PODT.RD_DATE AS RD_DATE, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_TEL_NO, PODT.PO_NO AS PO_NO, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, IVDT.INV_NO AS INV_NO, PODT.ITEM_AMT AS ITEM_AMT, POHD.AGENT AS AGENT, PODT.BUYER AS BUYER, POHD.PO_REMARK AS PO_REMARK, PODT.DELAY_REMARK, PODT.SCM_REMARK AS SCM_REMARK, IVHD.INV_DATE INV_DATE, PODT.PROCESS_TYPE AS PROCESS_TYPE, PODT.PLANT AS PLANT, POHD.OVERSEA_TO_LOCATION AS OVERSEA_TO_LOCATION, COD2.TEXT1 AS PURCHASE_DEPTT, PODT.PO_SEQ, PODT.BUYER_ITEM_NO, BYIT.DESCRIPTION_ENG, PODT.DESCRIPTION, PODT.SPECIFICATION, IVDT.INV_QTY, PODT.UNIT_MEASURE, PRDT.PURCHASER_ID, PRDT.EXP_FOR_UNIT_PRICE, PRDT.EXP_FOR_ITEM_AMT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = PODT.ORIGIN_CODE) AS ORIGIN_NAME, PODT.ACCOUNT_TYPE, PODT.MAKER_NAME, PODT.MAKER_CODE, NVL(F_SPLIT(PRDT.IV_COLUMN,'^',7), ' ') AS PURCHASER_SAMS, PRDT.RECIPIENT_NAME FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, ICOMIVDT IVDT, ICOMIVHD IVHD, ICOMCOD2 COD2, ICOMBYIT BYIT WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND IVDT.BUYER = IVHD.BUYER AND IVDT.INV_NO = IVHD.INV_NO AND PRDT.BUYER = COD2.COMPANY_CODE(+) AND COD2.TYPE(+) = 'C001' AND PRDT.PURCHASER_DEPT = COD2.CODE(+) AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND IVHD.STATUS <> 'D' AND PODT.PROCESS_TYPE = '0' AND NVL(IVDT.PKG_GR_QTY,0) = 0 AND PODT.BYIT_COMORG_CODE = BYIT.BUYER AND PODT.BUYER_ITEM_NO = BYIT.BUYER_ITEM_NO AND POHD.PKG_COMPANY_CODE =#{st_pkg_cmpy_no} AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND PRDT.EXP_CUR IS NOT NULL
AND PODT.BUYER IN
#{item}
AND POHD.AGENT = #{st_agent_code}
AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_purchase_dept}||'%')
AND IVDT.INV_NO LIKE #{st_inv_no}||'%'
AND PODT.PO_NO IN
#{item}
AND PODT.PO_NO LIKE #{st_po_no}||'%'
AND PODT.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
AND IVDT.INV_NO LIKE #{st_inv_no}||'%'
UNION ALL SELECT DECODE(PODT.ITEM_QTY,IVDT.INV_QTY,'입고예정','분할입고예정') AS STATUS, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER) AS BUYER_NAME, POHD.PO_CREATE_DATE AS PO_CREATE_DATE, PODT.RD_DATE AS RD_DATE, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_TEL_NO, PODT.PO_NO AS PO_NO, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, IVDT.INV_NO AS INV_NO, PODT.ITEM_AMT AS ITEM_AMT, POHD.AGENT AS AGENT, PODT.BUYER AS BUYER, POHD.PO_REMARK AS PO_REMARK, PODT.DELAY_REMARK, PODT.SCM_REMARK AS SCM_REMARK, IVDT.INV_DATE INV_DATE, PODT.PROCESS_TYPE AS PROCESS_TYPE, PODT.PLANT AS PLANT, POHD.OVERSEA_TO_LOCATION AS OVERSEA_TO_LOCATION, COD2.TEXT1 AS PURCHASE_DEPT, PODT.PO_SEQ, PODT.BUYER_ITEM_NO, BYIT.DESCRIPTION_ENG, PODT.DESCRIPTION, PODT.SPECIFICATION, IVDT.INV_QTY, PODT.UNIT_MEASURE, PRDT.PURCHASER_ID, PRDT.EXP_FOR_UNIT_PRICE, PRDT.EXP_FOR_ITEM_AMT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = PODT.ORIGIN_CODE) AS ORIGIN_NAME, PODT.ACCOUNT_TYPE, PODT.MAKER_NAME, PODT.MAKER_CODE, NVL(F_SPLIT(PRDT.IV_COLUMN,'^',7), ' ') AS PURCHASER_SAMS, PRDT.RECIPIENT_NAME FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, WMSIVDT IVDT, ICOMCOD2 COD2, ICOMBYIT BYIT WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PRDT.BUYER = COD2.COMPANY_CODE(+) AND COD2.TYPE(+) = 'C001' AND PRDT.PURCHASER_DEPT = COD2.CODE(+) AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE != '0' AND NVL(IVDT.PKG_GR_QTY,0) = 0 AND PODT.BYIT_COMORG_CODE = BYIT.BUYER AND PODT.BUYER_ITEM_NO = BYIT.BUYER_ITEM_NO AND POHD.PKG_COMPANY_CODE =#{st_pkg_cmpy_no} AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND PRDT.EXP_CUR IS NOT NULL
AND PODT.BUYER IN
#{item}
AND POHD.AGENT = #{st_agent_code}
AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_purchase_dept}||'%')
AND PODT.PO_NO IN
#{item}
AND PODT.PO_NO LIKE #{st_po_no}||'%'
AND PODT.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
AND IVDT.INV_NO LIKE #{st_inv_no}||'%'
) A WHERE A.STATUS LIKE '%'||#{st_status_check}||'%' ORDER BY A.BUYER_NAME, A.PO_NO, A.PO_SEQ
